// n8n Code node — Run Once for All Items
// Cloud-safe: no require(), does NOT depend on global URL being present.
// Uses Firecrawl's `data.links` when available. Falls back to parsing markdown/html for links.

// ============================================================================
// STRING + URL PARSING (NO global URL dependency)
// ============================================================================

function normStr(s) {
  return (s ?? "")
    .toString()
    .trim()
    .replace(/[\u200B-\u200D\uFEFF]/g, "")  // strip zero-width chars
    .replace(/[\u0000-\u001F\u007F]/g, ""); // strip control chars
}

function asArray(x) {
  if (!x) return [];
  return Array.isArray(x) ? x : [x];
}

function stripHashAny(urlStr) {
  const s = normStr(urlStr);
  const i = s.indexOf("#");
  return i >= 0 ? s.slice(0, i) : s;
}

function isBadScheme(href) {
  const h = (href ?? "").toString().toLowerCase();
  return h.startsWith("mailto:") || h.startsWith("tel:") || h.startsWith("javascript:") || h.startsWith("data:");
}

// Parse only what we need (origin/hostname/path/query) via regex.
function parseHttpUrlParts(u) {
  const s = normStr(u);
  const m = /^(https?):\/\/([^\/?#]+)(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i.exec(s);
  if (!m) return null;
  const scheme = m[1].toLowerCase();
  const hostname = m[2];
  const pathname = m[3] || "/";
  const search = m[4] || "";
  const hash = m[5] || "";
  const origin = `${scheme}://${hostname}`;
  return { href: `${origin}${pathname}${search}${hash}`, origin, hostname, pathname, search, hash, scheme };
}

function stripTrackingParamsString(urlStr) {
  // very small + safe: remove common tracking params; keeps other params
  const parts = parseHttpUrlParts(urlStr);
  if (!parts) return urlStr;

  const qs = parts.search || "";
  if (!qs || qs === "?") return `${parts.origin}${parts.pathname}`;

  const raw = qs.startsWith("?") ? qs.slice(1) : qs;
  const pairs = raw.split("&").filter(Boolean);

  const drop = new Set(["utm_source","utm_medium","utm_campaign","utm_term","utm_content","gclid","fbclid"]);
  const kept = [];
  for (const p of pairs) {
    const k = (p.split("=")[0] || "").trim();
    if (!drop.has(k)) kept.push(p);
  }

  const newQs = kept.length ? `?${kept.join("&")}` : "";
  return `${parts.origin}${parts.pathname}${newQs}`;
}

function canonicalizeNoURL(urlStr) {
  const s = normStr(urlStr);
  const parts = parseHttpUrlParts(s);
  if (!parts) return s;

  // normalize trailing slash (except root)
  let path = parts.pathname || "/";
  if (path !== "/" && /\/+$/.test(path)) path = path.replace(/\/+$/, "");

  const rebuilt = `${parts.origin}${path}${parts.search || ""}`;
  const noTrack = stripTrackingParamsString(rebuilt);
  return noTrack;
}

function isAssetPath(pathname) {
  return /\.(pdf|jpg|jpeg|png|gif|webp|svg|zip|rar|7z|mp4|mov|avi|mp3|wav|doc|docx|xls|xlsx|ppt|pptx|css|js)$/i.test(pathname || "");
}

function isJunkPath(path) {
  const p = (path || "").toLowerCase();
  return (
    p.includes("/wp-json") ||
    p.includes("/cdn-cgi/") ||
    p.includes("/cart") ||
    p.includes("/checkout") ||
    p.includes("/login") ||
    p.includes("/account") ||
    p.includes("/privacy") ||
    p.includes("/terms") ||
    p.includes("/cookie") ||
    p.includes("/sitemap") ||
    p.includes("/feed")
  );
}

// Very small resolver for relative URLs if they appear (Firecrawl usually gives absolute).
function resolveMaybeRelative(href, baseOrigin) {
  const h = normStr(href);
  const b = normStr(baseOrigin);

  if (!h) return null;

  // already absolute http(s)
  if (/^https?:\/\//i.test(h)) return h;

  // protocol-relative
  if (h.startsWith("//") && /^https?:\/\//i.test(b)) {
    const base = parseHttpUrlParts(b);
    if (!base) return null;
    return `${base.scheme}:${h}`;
  }

  // absolute path
  if (h.startsWith("/") && /^https?:\/\//i.test(b)) {
    const base = parseHttpUrlParts(b);
    if (!base) return null;
    return `${base.origin}${h}`;
  }

  // plain relative: just join to origin + "/"
  const base = parseHttpUrlParts(b);
  if (!base) return null;
  const joined = `${base.origin}/${h.replace(/^\.?\//, "")}`;
  return joined;
}

function takeN(arr, n) { return arr.slice(0, n); }

// ============================================================================
// SCORING / BUCKETING
// ============================================================================

const KW = {
  about: ["about","who-we-are","our-story","company","team","our-team","meet-the-team","leadership","values","mission"],
  services: ["services","service","what-we-do","solutions","treatments","repairs","maintenance","install","installation","book","booking","classes","workshops"],
  shop: ["shop","store","products","product","menu","order","buy","catalog","catalogue","collection","product-category"],
  contact: ["contact","get-in-touch","reach-us","find-us","location","locations","directions","call","email"],
  proof: ["testimonials","reviews","case-studies","case-study","portfolio","projects","gallery","work","clients"],
};

function scoreUrl(urlStr) {
  const parts = parseHttpUrlParts(urlStr);
  if (!parts) return { score: 0, bucket: "other" };

  const full = parts.href.toLowerCase();
  const path = (parts.pathname || "").toLowerCase();

  let score = 0;
  let bucket = "other";

  // Hard bucket rules
  // 1. Contact page priority (highest)
  if (path === "/contact" || path.startsWith("/contact/")) {
    bucket = "contact";
    score += 120;
  }

  // 2. Shop bucket (only if still 'other')
  if (bucket === "other" && (path.startsWith("/product-category/") || path.startsWith("/product/") || path === "/shop" || path.startsWith("/shop/"))) {
    bucket = "shop";
    score += 60;
  } else if (path.includes("/our-shops") || path.includes("/locations") || path.includes("/find-us")) {
    bucket = "contact";
    score += 50;
  } else if ((path.includes("class") || path.includes("booking") || path.includes("book")) && bucket !== "contact") {
    bucket = "services";
    score += 40;
  }

  const addIfMatch = (bucketName, kws, pts) => {
    for (const k of kws) {
      if (path.includes(k) || full.includes(`/${k}`)) {
        score += pts;
        if (bucket === "other") bucket = bucketName;
        break;
      }
    }
  };

  addIfMatch("contact", KW.contact, 80);
  addIfMatch("services", KW.services, 70);
  addIfMatch("about", KW.about, 60);
  addIfMatch("shop", KW.shop, 55);
  addIfMatch("proof", KW.proof, 50);

  // prefer shallower URLs
  const depth = path.split("/").filter(Boolean).length;
  score += Math.max(0, 20 - depth * 4);

  // penalize lots of query params
  const qpCount = parts.search ? parts.search.slice(1).split("&").filter(Boolean).length : 0;
  score -= Math.max(0, qpCount) * 4;

  if (isJunkPath(path)) score -= 50;

  return { score, bucket };
}

// ============================================================================
// LINK EXTRACTION (PREFER firecrawlData.links)
// ============================================================================

function extractLinksFromMarkdown(md) {
  const s = normStr(md);
  if (!s) return [];
  // markdown links: [text](url)
  const re = /\[[^\]]*\]\(([^)]+)\)/g;
  const out = [];
  let m;
  while ((m = re.exec(s)) !== null) out.push(m[1]);
  return out;
}

function extractLinksFromHtml(html) {
  const s = normStr(html);
  if (!s) return [];
  const re = /href=["']([^"']+)["']/gi;
  const out = [];
  let m;
  while ((m = re.exec(s)) !== null) out.push(m[1]);
  return out;
}

// ============================================================================
// MAIN
// ============================================================================

const items = $input.all();
const out = [];

for (const item of items) {
  const firecrawlData = item.json?.data ?? item.json ?? {};
  const metadata = firecrawlData.metadata ?? {};

  const markdown = normStr(firecrawlData.markdown);
  const html = normStr(firecrawlData.html);

  const inputUrl =
    normStr(metadata.url) ||
    normStr(metadata.ogUrl) ||
    normStr(metadata.sourceURL) ||
    normStr(item.json?.url);

  const baseParts = parseHttpUrlParts(stripHashAny(inputUrl));
  if (!baseParts) {
    out.push({
      json: {
        ok: false,
        error: { code: "bad_url", message: "Could not parse URL", url: inputUrl },
        debug: { inputUrl }
      }
    });
    continue;
  }

  const baseOrigin = baseParts.origin;
  const baseHostname = baseParts.hostname;

  // 1) Prefer Firecrawl links output (your setup shows it returns `data.links`)
  let rawLinks = firecrawlData.links ?? firecrawlData?.data?.links ?? [];
  rawLinks = asArray(rawLinks);

  // 2) If empty, fallback to markdown links, then html hrefs
  let fallbackUsed = false;
  if (rawLinks.length === 0) {
    const mdLinks = extractLinksFromMarkdown(markdown);
    const htmlLinks = extractLinksFromHtml(html);
    rawLinks = [...mdLinks, ...htmlLinks];
    fallbackUsed = true;
  }

  // Normalize, resolve (if relative), filter
  const seen = new Set();
  const candidates = [];

  const rejected = {
    badScheme: 0,
    notHttp: 0,
    couldntParse: 0,
    originMismatch: 0,
    asset: 0,
    dup: 0,
  };

  for (const hrefRaw of rawLinks) {
    const href = normStr(hrefRaw);
    if (!href || isBadScheme(href)) { rejected.badScheme++; continue; }

    const resolved = resolveMaybeRelative(href, baseOrigin);
    if (!resolved) { rejected.notHttp++; continue; }

    const parts = parseHttpUrlParts(stripHashAny(resolved));
    if (!parts) { rejected.couldntParse++; continue; }

    // same hostname only (stronger than origin when sites flip http/https in weird cases)
    if (parts.hostname !== baseHostname) { rejected.originMismatch++; continue; }

    if (isAssetPath(parts.pathname)) { rejected.asset++; continue; }

    const canon = canonicalizeNoURL(parts.href);
    if (seen.has(canon)) { rejected.dup++; continue; }
    seen.add(canon);

    const { score, bucket } = scoreUrl(canon);
    candidates.push({ url: canon, bucket, score });
  }

  candidates.sort((a, b) => b.score - a.score);

  // Build categorized_links first
  const categorized_links = {
    about: takeN(candidates.filter(c => c.bucket === "about").map(c => c.url), 2),
    shop: takeN(candidates.filter(c => c.bucket === "shop").map(c => c.url), 2),
    services: takeN(candidates.filter(c => c.bucket === "services").map(c => c.url), 2),
    contact: takeN(candidates.filter(c => c.bucket === "contact").map(c => c.url), 1),
    proof: takeN(candidates.filter(c => c.bucket === "proof").map(c => c.url), 2),
    other: takeN(candidates.filter(c => c.bucket === "other").map(c => c.url), 3),
  };

  // Build tier1 intentionally from categorized_links buckets
  const tier1 = [
    ...categorized_links.about,
    ...categorized_links.services,
    ...categorized_links.contact,
    ...categorized_links.proof,
    ...categorized_links.shop
  ];

  // tier2 is everything else
  const tier1Set = new Set(tier1);
  const tier2 = candidates.filter(c => !tier1Set.has(c.url)).map(c => c.url);

  out.push({
    json: {
      ok: true,
      url: baseParts.href,
      root_origin: baseHostname,

      markdown,
      metadata,

      tier1,
      tier2,
      categorized_links,
      all_internal_links: candidates.map(c => c.url),

      // keep for downstream compatibility
      hrefs: [...tier1, ...tier2].slice(0, 25),

      debug: {
        used_firecrawl_links: (firecrawlData.links ?? firecrawlData?.data?.links ?? []).length > 0,
        fallback_used: fallbackUsed,
        raw_links_count: rawLinks.length,
        total_candidates: candidates.length,
        rejected,
        top10_scored: candidates.slice(0, 10),
      }
    }
  });
}

return out;
